      ],
      "footnotes": [
        {"marker": "93", "text_start": "Ibid., pp. 28-29 : « Deshalb ist das Denken, wenn es für sich genommen wird, nicht \"praktisch\"."},
        {"marker": "94", "text_start": "Ibid., pp. 148-149 : « Die Antwort lautet : dieses Denken ist weder theoretisch noch praktisch. Es ereignet sich vor dieser Unterscheidung."}
      ],
